  /** Load a single key; coalesces with other loads in the same microtask window. */
  load(key: K): Promise<V>;
  /** Load many keys in one go (still deduped + cached); resolves an aligned array. */
  loadMany(keys: K[]): Promise<V[]>;
  /** Remove a key from the memoization cache so the next load re-fetches it. */
  clear(key: K): void;
}

/**
 * Create a loader that batches concurrent `load` calls into a single
 * `batchFn(keys)` invocation per microtask window.
 *
 * Contract for `batchFn`:
 *   - receives a deduplicated array of keys
 *   - must resolve with an array of results aligned with those keys
 *   - placing an `Error` at index i rejects only the caller of keys[i]
 *
 * Results are memoized across batches until evicted via `clear`.
 */
export function createLoader<K, V>(
  batchFn: (keys: K[]) => Promise<Array<V | Error>>,
): Loader<K, V> {
  const cache = new Map<K, V>();

  // Pending state for the current microtask window.
  let queued = false;
  let batchKeys: K[] = [];
  const pendingCalls = new Map<
    K,
    Array<(value: V) => void>
  >(); // key -> resolvers awaiting it this batch

  function flush(): void {
    queued = false;
    const keys = batchKeys;
    const calls = new Map(pendingCalls);
    batchKeys = [];
    pendingCalls.clear();

    // Serve everything we already have from cache.
    const missing: K[] = [];
    for (const k of keys) {
      if (!cache.has(k)) {
        if (!calls.has(k)) calls.set(k, []);
        missing.push(k);
      }
    }

    // Keys that were entirely cache hits have no callers registered in `calls`
    // unless someone else queued them; register empty arrays so map stays tidy.
    if (missing.length === 0) return;

    // Deduplicate is inherent to the Map/set below.
    const uniqueMissing = [...new Set(missing)];
    const dispatch = new Map<K, Array<(value: V) => void>>();
    for (const k of uniqueMissing) {
      dispatch.set(k, calls.get(k) ?? []);
    }

    batchFn(uniqueMissing).then(
      (results) => {
        if (!Array.isArray(results) || results.length !== uniqueMissing.length) {
          const err = new Error(
            `batchFn must resolve an array aligned with its ${uniqueMissing.length} input keys`,
          );
          for (const [k, resolvers] of dispatch) {
            void k;
            rejectAll(resolvers, err);
          }
          return;
        }
        results.forEach((result, i) => {
          const key = uniqueMissing[i];
          if (result instanceof Error) {
            // Per-key failure: reject only this key's callers, don't cache.
            rejectAll(dispatch.get(key)!, result);
          } else {
            cache.set(key, result as V);
            resolveAll(dispatch.get(key)!, result as V);
          }
        });
      },
      (err) => {
        // batchFn itself failed: reject all callers in this batch.
        for (const [, resolvers] of dispatch) rejectAll(resolvers, err);
      },
    );
  }

  return {
    load(key: K): Promise<V> {
      const cached = cache.get(key);
      if (cached !== undefined || cache.has(key)) {
        return Promise.resolve(cached as V);
      }
      let existing = pendingCalls.get(key);
      if (!existing) {
        existing = [];
        pendingCalls.set(key, existing);
        batchKeys.push(key);
      }
      const promise = new Promise<V>((resolve, reject) => {
        existing!.push(resolve);
        // Stash reject alongside via a side channel on the array object.
        (existing! as any)._rejects ??= [];
        (existing! as any)._rejects.push(reject);
      });
      if (!queued) {
        queued = true;
        queueMicrotask(() => flush());
      }
      return promise;
    },

    async loadMany(keys: K[]): Promise<V[]> {
      return Promise.all(keys.map((key) => this.load(key)));
    },

    clear(key: K): void {
      cache.delete(key);
    },
  };
}

function resolveAll(resolvers: Array<(v: any) => void>, value: any): void {
  for (const r of resolvers) r(value);
}

function rejectAll(resolvers: any[], error: Error): void {
  const rejects = (resolvers as any)._rejects ?? [];
  for (const r of rejects) r(error);
}
