interface Waiter<V> {
  resolve: (value: V) => void;
  reject: (error: unknown) => void;
}

/**
 * Create a loader that batches concurrent `load` calls into a single
 * `batchFn(keys)` invocation per microtask window.
 *
 * Contract for `batchFn`:
 *   - receives a deduplicated array of keys
 *   - must resolve with an array of results aligned with those keys
 *   - placing an `Error` at index i rejects only the caller of keys[i]
 *
 * Results are memoized across batches until evicted via `clear`.
 */
export function createLoader<K, V>(
  batchFn: (keys: K[]) => Promise<Array<V | Error>>,
): Loader<K, V> {
  const cache = new Map<K, V>();

  // State for the current microtask window.
  let queued = false;
  const waiters = new Map<K, Array<Waiter<V>>>();

  function scheduleFlush(): void {
    if (queued) return;
    queued = true;
    queueMicrotask(() => {
      queued = false;

      // Serve cache hits immediately; collect what still needs fetching.
      for (const [key, ws] of waiters) {
        if (!cache.has(key)) continue;
        const value = cache.get(key)!;
        for (const w of ws) w.resolve(value);
        waiters.delete(key);
      }

      if (waiters.size === 0) return;

      // Map keys are unique by construction -> deduplicated batch.
      const keys = [...waiters.keys()];
      const thisBatch = new Map(waiters);
      waiters.clear();

      batchFn(keys).then(
        (results) => {
          if (!Array.isArray(results) || results.length !== keys.length) {
            const err = new Error(
              `batchFn must resolve an array aligned with its ${keys.length} input keys`,
            );
            for (const ws of thisBatch.values()) failAll(ws, err);
            return;
          }
          keys.forEach((key, i) => {
            const result = results[i];
            const ws = thisBatch.get(key)!;
            if (result instanceof Error) {
              // Per-key failure: reject only this key's callers; don't cache.
              failAll(ws, result);
            } else {
              cache.set(key, result as V);
              for (const w of ws) w.resolve(result as V);
            }
          });
        },
        (err) => {
          // batchFn itself rejected: reject every caller in this batch.
          for (const ws of thisBatch.values()) failAll(ws, err);
        },
      );
    });
  }

  return {
    load(key: K): Promise<V> {
      // Memoized from a previous batch?
      if (cache.has(key)) return Promise.resolve(cache.get(key)!);

      let ws = waiters.get(key);
      if (!ws) {
        ws = [];
        waiters.set(key, ws);
        scheduleFlush();
      }
      return new Promise<V>((resolve, reject) => {
        ws!.push({ resolve, reject });
      });
    },

    async loadMany(keys: K[]): Promise<V[]> {
      return Promise.all(keys.map((key) => this.load(key)));
    },

    clear(key: K): void {
      cache.delete(key);
    },
  };
}

function failAll<V>(waiters: Array<Waiter<V>>, error: unknown): void {
  for (const w of waiters) w.reject(error);
}
