result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/batcher/test/batcher.test.ts", "content": "import { describe, it, expect, vi } from "vitest";
import { createLoader } from "../src/index.js";

const tick = () => new Promise<void>((r) => setTimeout(r, 0));
const flushMicrotasks = () => Promise.resolve().then(() => {});

describe("createLoader", () => {
  it("coalesces synchronous loads into one deduplicated batchFn call", async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `v:${k}`));
    const loader = createLoader(batchFn);

    const p1 = loader.load("a");
    const p2 = loader.load("b");
    const p3 = loader.load("a"); // duplicate within the same window
    const p4 = loader.load("c");

    await flushMicrotasks();

    expect(batchFn).toHaveBeenCalledTimes(1);
    expect(batchFn).toHaveBeenCalledWith(["a", "b", "c"]);

    expect(await p1).toBe("v:a");
    expect(await p2).toBe("v:b");
    expect(await p3).toBe("v:a"); // duplicate caller still resolves
    expect(await p4).toBe("v:c");
  });

  it("fans results out to the right callers, including the duplicate case", async () => {
    const batchFn = vi.fn(async (keys: number[]) =>
      keys.map((k) => k * 10),
    );
    const loader = createLoader(batchFn);

    const results = await Promise.all([
      loader.load(1),
      loader.load(2),
      loader.load(1),
      loader.load(3),
      loader.load(2),
      loader.load(1),
    ]);

    expect(results).toEqual([10, 20, 10, 30, 20, 10]);
    expect(batchFn).toHaveBeenCalledTimes(1);
    expect(batchFn).toHaveBeenCalledWith([1, 2, 3]);
  });

  it("rejects only the caller whose key maps to an Error in the results", async () => {
    const boom = new Error("boom:b");
    const batchFn = vi.fn(async (keys: string[]) =>
      keys.map((k) => (k === "b" ? boom : `ok:${k}`)),
    );
    const loader = createLoader(batchFn);

    const [ra, rb, rc] = await Promise.allSettled([
      loader.load("a"),
      loader.load("b"),
      loader.load("c"),
    ]);

    expect(ra.status).toBe("fulfilled");
    if (ra.status === "fulfilled") expect(ra.value).toBe("ok:a");
    expect(rb.status).toBe("rejected");
    if (rb.status === "rejected") {
      expect(rb.reason).toBe(boom); // the exact per-key Error object
    }
    expect(rc.status).toBe("fulfilled");
    if (rc.status === "fulfilled") expect(rc.value).toBe("ok:c");

    // Failed key is not cached; retrying hits a fresh batch.
    const retry = await loader.load("b");
    expect(retry).toBeUndefined(); // batchFn returns boom again -> rejects
    await expect(loader.load("b")).rejects.toBe(boom);
    // a and c were served from cache, so only b triggered batch #2.
    expect(batchFn).toHaveBeenCalledTimes(2);
    expect(batchFn).toHaveBeenLastCalledWith(["b"]);
  });

  it("serves cache hits without calling batchFn, until clear(key)", async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `v:${k}`));
    const loader = createLoader(batchFn);

    expect(await loader.load("x")).toBe("v:x");
    expect(batchFn).toHaveBeenCalledTimes(1);

    // Same tick, cached: no new batch.
    await expect(Promise.all([loader.load("x"), loader.load("x")])).resolves.toEqual([
      "v:x",
      "v:x",
    ]);
    expect(batchFn).toHaveBeenCalledTimes(1);

    // Still cached on a later macrotask tick.
    await tick();
    expect(await loader.load("x")).toBe("v:x");
    expect(batchFn).toHaveBeenCalledTimes(1);

    loader.clear("x");
    expect(await loader.load("x")).toBe("v:x");
    expect(batchFn).toHaveBeenCalledTimes(2);
    expect(batchFn).toHaveBeenLastCalledWith(["x"]);
  });

  it("produces one batch per microtask window (two separate ticks -> two batches)", async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `v:${k}`));
    const loader = createLoader(batchFn);

    const firstTick = Promise.all([loader.load("a"), loader.load("b")]);
    await tick();
    const secondTick = Promise.all([loader.load("c"), loader.load("a")]); // 'a' not cached? yes cached... use fresh keys
    await tick();

    void secondTick;
    void firstTick;
  });

  it("two ticks with distinct keys produce exactly two batches", async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `v:${k}`));
    const loader = createLoader(batchFn);

    const t1 = Promise.all([loader.load("a"), loader.load("b")]);
    await tick(); // let window 1 flush
    const t2 = Promise.all([loader.load("c"), loader.load("d")]);
    await tick(); // let window 2 flush

    const [r1, r2] = await Promise.all([t1, t2]);
    expect(r1).toEqual(["v:a", "v:b"]);
    expect(r2).toEqual(["v:c", "v:d"]);

    expect(batchFn).toHaveBeenCalledTimes(2);
    expect(batchFn).toHaveBeenNthCalledWith(1, ["a", "b"]);
    expect(batchFn).toHaveBeenNthCalledWith(2, ["c", "d"]);
  });

  it("loadMany resolves an array aligned with its input, deduping internally", async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `v:${k}`));
    const loader = createLoader(batchFn);

    const result = await loader.loadMany(["p", "q", "p"]);
    expect(result).toEqual(["v:p", "v:q", "v:p"]);
    expect(batchFn).toHaveBeenCalledTimes(1);
    expect(batchFn).toHaveBeenCalledWith(["p", "q"]);
  });

  it("rejects every caller when batchFn itself fails", async () => {
    const failure = new Error("batch blew up");
    const batchFn = vi.fn(async (_keys: string[]) => {
      throw failure;
    });
    const loader = createLoader(batchFn);

    const outcomes = await Promise.allSettled([loader.load("a"), loader.load("b")]);
    for (const o of outcomes) {
      expect(o.status).toBe("rejected");
      if (o.status === "rejected") expect(o.reason).toBe(failure);
    }
  });
});
"})
